-- desc: 获取客户端业务配置参数接口
-- api: system.config.check
-- doc: https://yuque.antfin-inc.com/ejoy-platform/ejoy-platform/qs19z6
-- params:
-- @param configCheckTime: long, 配置检查时间
-- return:
-- configCheckTime: long, 配置检查时间
-- clientConfig: json, key-value配置项
function M.usercenter_system_config_check(config_check_time, cb)
    E.LOG.debug(TAG, 'usercenter_system_config_check begin')
    local params = {}
    params.configCheckTime = config_check_time
    --E.log(params)

    UP.post(UP.SERVICE.CONFIG_CHECK, params, function(succ, ...)
        if succ then
            local data = ...
            cb(true, data)
        else
            local code, msg = ...
            cb(false, code, msg)
        end
    end)
end

-- desc: 账号中心登录
-- api: account.thirdParty.login
-- doc: https://yuque.antfin-inc.com/ejoy-platform/ejoy-platform/ndwxug
-- params:
-- @param third_party_type: string, 账号类型(google,apple,facebook,qookka,guest,mock)
-- @param third_party_token: string, 第三方账号授权登录成功后返回的用于服务器获取信息的令牌。当thirdPartyType=guest时， thirdPartyToken={agstToken}
-- @param agst_token: string, agstToken
-- @param is_create: thirdPartyType等于facebook/google/apple/qookka时有效, true:  创建新账号
-- @param migrateToken: 用于转移外部账号
-- @param risk 风险数据
-- return:
-- token: string, 登录会话ID
-- tokenTimeout: int, 返回的token过期的时间(单位:秒)
function M.usercenter_login(third_party_type, third_party_token, agst_token, migrate_token, is_create, risk, cb)
    E.LOG.debug(TAG, 'usercenter_login begin')
    local params = {}
    params.thirdPartyType = third_party_type
    params.thirdPartyToken = third_party_token
    params.agstToken = agst_token
    params.isCreate = is_create
    params.risk = risk

    if migrate_token and '' ~= migrate_token then
        -- BBGame 迁移特有字段
        params.migrateToken = migrate_token
    end

    --E.log(params)

    UP.post(UP.SERVICE.LOGIN, params, function(succ, ...)
        if succ then
            local data = ...
            cb(true, data)
        else
            local code, msg, data = ...
            cb(false, code, msg, data)
        end
    end)
end

