function M.get_pre_order_status(platform, items,cb)
    local params = {
        bundleId =  E.Sysinfo.package_name(),
        bizAppId = E.get_game_id(),
        reserveIds = items,
        platform = platform
    }

    UP.post(UP.SERVICE.RESERVER_CHECK,params,function(succ,...)
        if cb then
